package com.hms.branches;
import com.hms.tenancy.*; import jakarta.validation.Valid; import java.util.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/hospitals/{tenantSlug}/branches") public class BranchStatusController {private final TenantRepository tenants;private final HospitalBranchRepository branches;public BranchStatusController(TenantRepository t,HospitalBranchRepository b){tenants=t;branches=b;} @PatchMapping("/{branchId}/status") public HospitalBranch update(@PathVariable String tenantSlug,@PathVariable UUID branchId,@Valid @RequestBody UpdateBranchStatusRequest r){UUID tenant=tenants.findBySlug(tenantSlug).map(Tenant::getId).orElseThrow(()->new TenantNotFoundException(tenantSlug));HospitalBranch b=branches.findById(branchId).filter(x->x.getTenantId().equals(tenant)).orElseThrow(()->new IllegalArgumentException("Branch not found"));branches.updateActive(branchId,tenant,r.active());return branches.findById(b.getId()).orElseThrow();}}
